# [SAME-SCENARIO] extract_json.py\nimport os\nfrom model_client import get_llm_client\nfrom model_models import PromptRequest, normalize_response\n\ndef extract_json(text: str) -> dict:\n    """Extract structured JSON from the provided text using a hosted LLM.\n    Uses the provider configured in environment variables."""\n    client = get_llm_client()\n    request = PromptRequest(\n        messages=[{\n            \"role\": \"user\",\n            \"content\": f\"Extract the following information as JSON:\\n{text}\"\n        }],\n        model=\"gpt-4o-mini\",  # Model identifier for the selected provider\n    )\n    response = client.chat_completions(request)\n    result = normalize_response(response)\n    # Expect response to contain a JSON string in the first message content\n    json_str = result[\"choices\"][0][\"message\"][\"content\"].strip()\n    import json\n    return json.loads(json_str)\n